 "content": "from collections import Counter

def transform(grid):
    """Draw color-3 segments between aligned non-background markers."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    marker_color = grid[markers[0][0]][markers[0][1]] if markers else None
    out = [row[:] for row in grid]
    for i, (r1, c1) in enumerate(markers):
        for r2, c2 in markers[i + 1:]:
            if r1 == r2:
                for c in range(min(c1, c2) + 1, max(c1, c2)):
                    if grid[r1][c] == background:
                        out[r1][c] = 3
            elif c1 == c2:
                for r in range(min(r1, r2) + 1, max(r1, r2)):
                    if grid[r][c1] == background:
                        out[r][c1] = 3
    return out
